package main

import (
    "fmt"
    s "strings"
)
 func main() {
    var l int
    var str string
    fmt.Scan(&l, &str)
    fs := s.Count(str, "FS")
    sf := s.Count(str, "SF")
    if sf > fs {
        fmt.Println("YES")
    } else {
        fmt.Println("NO")
    }
}
